int __fastcall GetRoomByCoordsByLevel(D2DrlgStrc * pDrlg, int32_t nX, int32_t nY) {
    D2DrlgLevelStrc* pLevel = pDrlg->pLevel;
    while (true) {
      BOOL bIsInside;
      if (!pLevel) {
        return 0;
      }

      bIsInside = DrlgRoom::AreXYInsideCoordinates(&pLevel->sCoordinatesAndSize, nX, nY);
      if (bIsInside) {
        break;
      }

      pLevel = pLevel->pLevelNext;
    }

    return pLevel->eD2LevelId;
}

eAct __stdcall GetActNoFromLevelNumber(eD2LevelId eLevel) {
    // Static local variables (originally global data)
    static int aActTownLevelId[6] = { 0x1, 0x28, 0x4b, 0x67, 0x6d, 0x400 };

    int i = 1;
    do {
      if ((int)eLevel < aActTownLevelId[i]) {
        return (char)i - ACT_II;
      }

      i++;
    } while (i < 6);

    return ACT_I;
}

