// Level-placement direction-enumeration callback restricted to 2 adjacent directions (dirs 1 and 2). On first call picks one of the two randomly from the seeded RNG; on the second call tries the other; returns FALSE when both are exhausted. Computes candidate world-position of the current node relative to its predecessor for each tried direction. Used by the placement backtracker for corridors/narrow-linkage nodes.
BOOL __fastcall DRLGPLACE_Adjacent2DirRandom(D2DrlgLevelPlacementStrc * pLevelUnknown) {
    D2SeedStrc sNextSeed;
    int nNodeIdx = pLevelUnknown->nCurrentNode;
    if (pLevelUnknown->aInitialDir[nNodeIdx] == -1) {
      sNextSeed = D2_SEED_NEXT(pLevelUnknown->sSeed);
      pLevelUnknown->sSeed = sNextSeed;
      pLevelUnknown->aInitialDir[nNodeIdx] = (sNextSeed.nSeedLow & 1) + 1;
      pLevelUnknown->aCurrentDir[pLevelUnknown->nCurrentNode] = pLevelUnknown->aInitialDir[pLevelUnknown->nCurrentNode];
    } else {
      int nNextDir;
      nNextDir = 2 - (uint32_t)(pLevelUnknown->aCurrentDir[nNodeIdx] != 1);
      if (nNextDir == pLevelUnknown->aInitialDir[nNodeIdx]) {
        return 0;
      }

      pLevelUnknown->aCurrentDir[nNodeIdx] = nNextDir;
    }

    nNodeIdx = pLevelUnknown->nCurrentNode;
    D2DrlgCoordsStrc* pPrevCoordsEntry = pLevelUnknown->aCoordsAndSize + pLevelUnknown->pLevelData->aEntry[nNodeIdx].nNodeLevelEntryIdPrev;
    if (pLevelUnknown->aCurrentDir[nNodeIdx] != 1) {
      switch (pLevelUnknown->aCurrentDir[nNodeIdx]) {
        case 0:
          pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldSize.x - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.x + pPrevCoordsEntry->WorldPosition.x;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldSize.y + pPrevCoordsEntry->WorldPosition.y;
        return 1;
        case 1:
          pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.x;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldSize.y - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.y + pPrevCoordsEntry->WorldPosition.y;
        return 1;
        case 2:
          pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.y;
        return 1;
        case 3:
          pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldSize.x + pPrevCoordsEntry->WorldPosition.x;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y;
      }

      return 1;
    }

    pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.x;
    pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y;
    return 1;
}

// For the current placement node, iterates through all 8 cardinal/diagonal directions (seeded randomly on first visit) and positions the node adjacent to its predecessor in the chosen direction. Returns FALSE when all 8 directions have been exhausted (backtrack signal).
BOOL __fastcall DRLGPLACE_Adjacent8DirAligned(D2DrlgLevelPlacementStrc * pLevelUnknown) {
    D2SeedStrc sNextSeed;
    int nNodeIdx = pLevelUnknown->nCurrentNode;
    if (pLevelUnknown->aInitialDir[nNodeIdx] == -1) {
      sNextSeed = D2_SEED_NEXT(pLevelUnknown->sSeed);
      pLevelUnknown->sSeed = sNextSeed;
      pLevelUnknown->aInitialDir[nNodeIdx] = sNextSeed.nSeedLow & 7;
      pLevelUnknown->aCurrentDir[pLevelUnknown->nCurrentNode] = pLevelUnknown->aInitialDir[pLevelUnknown->nCurrentNode];
    } else {
      uint32_t nNextDir;
      nNextDir = pLevelUnknown->aCurrentDir[nNodeIdx] + 1U & 0x80000007;
      if ((int)nNextDir < 0) {
        nNextDir = (nNextDir - 1 | -8) + 1;
      }
      if (nNextDir == pLevelUnknown->aInitialDir[nNodeIdx]) {
        return 0;
      }

      pLevelUnknown->aCurrentDir[nNodeIdx] = nNextDir;
    }

    nNodeIdx = pLevelUnknown->nCurrentNode;
    D2DrlgCoordsStrc* pPrevCoordsEntry = pLevelUnknown->aCoordsAndSize + pLevelUnknown->pLevelData->aEntry[nNodeIdx].nNodeLevelEntryIdPrev;
    switch (pLevelUnknown->aCurrentDir[nNodeIdx]) {
      case 0:

      case 1:
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x;
      pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldSize.y + pPrevCoordsEntry->WorldPosition.y;
      return 1;
      case 2:

      case 3:
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.x;
      pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y;
      return 1;
      case 4:

      case 5:
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x;
      pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.y;
      return 1;
      case 6:

      case 7:
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldSize.x + pPrevCoordsEntry->WorldPosition.x;
      pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y;
    }

    return 1;
}

// Places the current DRLG level node adjacent to its predecessor in one of 4 cardinal directions (dir 0-3), with random mirroring controlled by a single seed bit. Sets the node's WorldPosition relative to the previous node's WorldPosition+WorldSize; the mirrored path sets gdwDrlgLevelPlacementFlags=0x800000 (connector side flag) and the non-mirrored path sets 0x400000. Always returns TRUE.
BOOL __fastcall DRLGPLACE_Adjacent4DirMirrored(D2DrlgLevelPlacementStrc * pLevelUnknown) {
    LONG nPosY;
    pLevelUnknown->aInitialDir[pLevelUnknown->nCurrentNode] = 3;
    pLevelUnknown->aCurrentDir[pLevelUnknown->nCurrentNode] = pLevelUnknown->aInitialDir[pLevelUnknown->nCurrentNode];
    int nNodeIdx = pLevelUnknown->nCurrentNode;
    int nPrevNodeIdx = pLevelUnknown->pLevelData->aEntry[nNodeIdx].nNodeLevelEntryIdPrev;
    D2SeedStrc sNextSeed = D2_SEED_NEXT(pLevelUnknown->sSeed);
    pLevelUnknown->sSeed = sNextSeed;
    D2DrlgCoordsStrc* pPrevCoordsEntry = pLevelUnknown->aCoordsAndSize + nPrevNodeIdx;
    if ((uint64_t)d2_bits_of(sNextSeed) & 1) {
      switch (pLevelUnknown->aCurrentDir[pLevelUnknown->nCurrentNode]) {
        case 0:
          pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldSize.y + pPrevCoordsEntry->WorldPosition.y;
        gdwDrlgLevelPlacementFlags = 0x800000;
        return 1;
        case 1:
          gdwDrlgLevelPlacementFlags = 0x800000;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.x;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y;
        return 1;
        case 2:
          gdwDrlgLevelPlacementFlags = 0x800000;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldSize.x - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.x + pPrevCoordsEntry->WorldPosition.x;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.y;
        return 1;
        case 3:
          pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldSize.x + pPrevCoordsEntry->WorldPosition.x;
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = pPrevCoordsEntry->WorldSize.y - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.y + 8 + pPrevCoordsEntry->WorldPosition.y;
      }

      gdwDrlgLevelPlacementFlags = 0x800000;
      return 1;
    }

    switch (pLevelUnknown->aCurrentDir[pLevelUnknown->nCurrentNode]) {
      case 0:
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldSize.x - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.x + pPrevCoordsEntry->WorldPosition.x;
      nPosY = pPrevCoordsEntry->WorldSize.y + pPrevCoordsEntry->WorldPosition.y;
      break;
      case 1:
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.x;
      nPosY = pPrevCoordsEntry->WorldSize.y - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.y + pPrevCoordsEntry->WorldPosition.y;
      break;
      case 2:
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x;
      nPosY = pPrevCoordsEntry->WorldPosition.y - pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldSize.y;
      break;
      case 3:
        pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.x = pPrevCoordsEntry->WorldSize.x + pPrevCoordsEntry->WorldPosition.x;
      nPosY = pPrevCoordsEntry->WorldPosition.y - 8;
      break;
      default:
        {
          gdwDrlgLevelPlacementFlags = 0x400000;
          return 1;
        }
    }

    pLevelUnknown->aCoordsAndSize[nNodeIdx].WorldPosition.y = nPosY;
    gdwDrlgLevelPlacementFlags = 0x400000;
    return 1;
}

