    if (0 < nIndexMax) {
      D2DrlgCoordsStrc* pCoords;
      pCoords = pLevelUnknown->aCoordsAndSize;
      do {
        if (i != nPrevId) {
          _bNoOverlap = DrlgRoom::DRLGROOM_CoordsWithinDistance(pLevelUnknown->aCoordsAndSize + nIndexMax, pCoords, 0);
          if (!_bNoOverlap) {
            return 0;
          }
        }

        i++;
        pCoords++;
      } while (i < nIndexMax);
    }

    nPrevId = 1;
    if (!nIndexMax) {
      return nPrevId;
    }

    LONG* pWorldSizeY = &pLevelUnknown->aCoordsAndSize[0].WorldSize.y;
