    __frame1.nTargetX = (int)(nExitWorldX + (nExitWorldX >> 0x1f & 7U)) >> 3;
    nTargetGridYRaw = (int)(nTargetGridYRaw + (nTargetGridYRaw >> 0x1f & 7U)) >> 3;
